import React, { useEffect, useState } from 'react';
import Loading from '../../loading/Loading';
import CompanyMenu from '../Company_Menu/CompanyMenu';
import './CompanyOrder.css';
import { useDispatch, useSelector } from 'react-redux';
import { Buscar_Orders_Empresa } from '../../../Redux/Actions/Empresa/Actions-Empresa';

const CompanyOrders = () => {
  const [loading, setLoading] = useState(true);
  const Compras = useSelector((state) => state.ORDENES);
  const dispatch = useDispatch();
  const tienda = useSelector((state) => state.EMPRESA);
  const [companyId, setCompanyId] = useState(tienda.id); // ID de la empresa que deseas mostrar

  useEffect(() => {
    setCompanyId(tienda.id);
    const timer = setTimeout(() => {
      setLoading(false);
      dispatch(Buscar_Orders_Empresa(tienda.id)); // Llamar a la acción para buscar órdenes por empresa
    }, 3000); // Tiempo simulado de carga

    return () => clearTimeout(timer);
  }, [dispatch, tienda.id]);

  useEffect(() => {
    if (Compras) {
      console.log('Compras:', Compras); // Verificar en la consola si Compras tiene datos
    }
  }, [Compras]);

  const filterOrdersByCompany = (orders, companyId) => {
    return orders
      .map((order) => {
        const items = order.item.filter((item) => item.tienda === companyId);
        const costoTotal = items.reduce((total, item) => total + parseFloat(item.costo) * item.quantity, 0);
        return items.length > 0 ? { ...order, item: items, costoTotal } : null;
      })
      .filter((order) => order !== null);
  };

  const filteredOrders = filterOrdersByCompany(Compras, companyId);

  return (
    <>
      {loading ? <Loading /> : null}
      <CompanyMenu className="nav-menu" />
      <div className="body-orders">
        <h2>Lista de Pedidos</h2>
        <div className="table-container">
          {filteredOrders.length > 0 ? (
            <table>
              <thead>
                <tr>
                  <th># Orden</th>
                  <th>Items</th>
                  <th>Precio Total</th>
                  <th>Estado</th>
                </tr>
              </thead>
              <tbody>
                {filteredOrders.map((order) => (
                  <tr key={order.id} className={order.estado.toLowerCase()}>
                    <td>{order.id}</td>
                    <td>
                      {order.item.map((item, index) => (
                        <div key={index} className="items-container">
                          <p>Marca: {item.marca}</p>
                          <p>Modelo: {item.modelo}</p>
                          <p>Color: {item.color}</p>
                          <p>Talla: {item.talla}</p>
                          <p>Cantidad: {item.quantity}</p>
                          <img src={item.url} alt={item.descripcion} width="50" />
                        </div>
                      ))}
                    </td>
                    <td>{order.costoTotal}</td>
                    <td>{order.estado}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <p>No tienes compras </p>
          )}
        </div>
      </div>
    </>
  );
};

export default CompanyOrders;
